        version: s.version().to_owned(),
        name: s.name().to_owned(),
        trigger: s.trigger().clone(),
        inputs,
        vars: s.vars().to_vec(),
        secrets: s.secrets().to_vec(),
        steps: s.steps().to_vec(),
        result: s.result().cloned(),
        examples: s.examples().to_vec(),
